import { applyBootstrap } from './bootstrap.ts';
import type { D1Database, D1PreparedStatement } from '@cloudflare/workers-types';
import { ApiError, KINDS, freshness, nextReminderDue, object, scaledIngredients, stable, string, validateAdmin, validateData } from './domain.ts';
import type { Data, HubRecord, Kind } from './domain.ts';

/** Binding adapter; production Env is generated by the chosen Sites starter. */
export interface HubBindings { DB:D1Database; HUB_BOOTSTRAP_JSON?:string; }
interface Row { id:string;kind:Kind;data:string;version:number;created_at:string;updated_at:string; }
interface Operation { fingerprint:string;result_json:string; }
const MAX_BODY=100_000;
function json(value:unknown,status=200):Response { return Response.json(value,{status,headers:{'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Vary':'Cookie'}}); }
function record(row:Row):HubRecord { const data=JSON.parse(row.data) as Data;return {id:row.id,kind:row.kind,data:row.kind==='source'?{...data,freshness:freshness(data.lastSuccess)}:data,version:row.version,createdAt:row.created_at,updatedAt:row.updated_at}; }
function version(value:unknown):number { if(!Number.isSafeInteger(value)||Number(value)<1)throw new ApiError(400,'invalid_input','Include the current record version.');return Number(value); }
function identifier(value:unknown):string { const s=string(value,'ID',150);if(!/^[a-zA-Z0-9_-]+$/.test(s))throw new ApiError(400,'invalid_input','Invalid ID.');return s; }
function keyFor(request:Request,fallback?:unknown):string { const k=request.headers.get('Idempotency-Key')??fallback;const s=string(k,'Idempotency key',150);if(!/^[a-zA-Z0-9_-]{8,150}$/.test(s))throw new ApiError(400,'invalid_input','Use a unique idempotency key with at least 8 characters.');return s; }
async function digest(value:string):Promise<string> { const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return [...new Uint8Array(bytes)].map(v=>v.toString(16).padStart(2,'0')).join(''); }
async function body(request:Request):Promise<Data> {
 if(!request.headers.get('Content-Type')?.startsWith('application/json'))throw new ApiError(415,'invalid_content_type','Use JSON for this action.');
 if(Number(request.headers.get('Content-Length'))>MAX_BODY)throw new ApiError(413,'too_large','This request is too large.');
 const reader=request.body?.getReader();if(!reader)throw new ApiError(400,'invalid_input','Include request data.');let size=0;const chunks:Uint8Array[]=[];
 try {while(true){const part=await reader.read();if(part.done)break;size+=part.value.length;if(size>MAX_BODY){await reader.cancel();throw new ApiError(413,'too_large','This request is too large.');}chunks.push(part.value);}}finally{reader.releaseLock();}
 const bytes=new Uint8Array(size);let at=0;for(const c of chunks){bytes.set(c,at);at+=c.length;}
 try{return object(JSON.parse(new TextDecoder().decode(bytes)));}catch(e){if(e instanceof ApiError)throw e;throw new ApiError(400,'invalid_json','The request could not be read.');}
}
function checkOrigin(request:Request):void { if(request.headers.get('Origin')!==new URL(request.url).origin)throw new ApiError(403,'invalid_origin','Open the hub directly before making changes.');if(request.headers.get('Sec-Fetch-Site')==='cross-site')throw new ApiError(403,'invalid_origin','Cross-site changes are not allowed.'); }
async function membership(db:D1Database,userId:string,email?:string|null):Promise<'owner'|'member'> {
 const now=new Date().toISOString();
 await db.batch([
  db.prepare('INSERT INTO hub_owner(singleton,user_id,created_at) VALUES(1,?,?) ON CONFLICT(singleton) DO NOTHING').bind(userId,now),
  db.prepare("INSERT INTO hub_members(user_id,display_name,role,created_at) SELECT user_id,'Household owner','owner',created_at FROM hub_owner WHERE singleton=1 ON CONFLICT(user_id) DO NOTHING")
 ]);
 if(email){await db.prepare("INSERT INTO hub_members(user_id,display_name,role,created_at) SELECT ?,display_name,'member',? FROM hub_invites WHERE email=? ON CONFLICT(user_id) DO NOTHING").bind(userId,now,email.trim().toLowerCase()).run();}
 const found=await db.prepare('SELECT role FROM hub_members WHERE user_id=?').bind(userId).first<{role:'owner'|'member'}>();
 if(!found)throw new ApiError(403,'not_household_member','This account has not been added to this household. Ask the owner to grant Site access and household membership.');return found.role;
}
async function find(db:D1Database,id:string):Promise<Row> { const row=await db.prepare('SELECT id,kind,data,version,created_at,updated_at FROM hub_records WHERE id=?').bind(id).first<Row>();if(!row)throw new ApiError(404,'not_found','This item no longer exists.');return row; }
async function state(db:D1Database,admin:boolean):Promise<Data> {
 const result=await db.prepare('SELECT id,kind,data,version,created_at,updated_at FROM hub_records ORDER BY created_at,id LIMIT 2501').all<Row>();if(result.results.length>2500)throw new ApiError(503,'record_limit','The household has reached the current record limit. Export records and archive completed items.');
 return {records:result.results.map(record),serverTime:new Date().toISOString(),permissions:{admin},integrations:{recipeCapture:{configured:true,mode:'local_ocr',cloudAIConfigured:false,originalImagesStored:false},icloud:{configured:false,status:'awaiting_access'},backgroundTasks:{configured:false,status:result.results.some(r=>r.kind==='source')?'initial_snapshot_only':'awaiting_verified_import'}}};
}
async function preparedData(db:D1Database,kind:Kind,raw:unknown,previous?:Row):Promise<Data> {
 let data=validateData(kind,raw);
 if(kind==='meal'&&data.recipeId){const old=previous?JSON.parse(previous.data) as Data:undefined;
  if(old?.recipeId===data.recipeId&&old.recipeSnapshot)data={...data,recipeSnapshot:old.recipeSnapshot};
  else {const recipe=await find(db,String(data.recipeId));if(recipe.kind!=='recipe')throw new ApiError(400,'invalid_recipe','Choose a saved recipe.');data={...data,recipeSnapshot:JSON.parse(recipe.data)};}
 }
 if(kind==='reminder'&&previous){const old=JSON.parse(previous.data) as Data;if(!old.done&&data.done&&data.repeat!=='none'&&data.dueAt)data={...data,done:false,lastCompletedAt:new Date().toISOString(),dueAt:nextReminderDue(String(data.dueAt),String(data.repeat))};}
 return data;
}
async function createItem(request:Request,db:D1Database,userId:string,admin:boolean):Promise<Response> {
 const b=await body(request);if(!KINDS.includes(b.kind as Kind))throw new ApiError(400,'invalid_kind','Unknown item type.');const kind=b.kind as Kind;if(kind==='source'&&!admin)throw new ApiError(403,'owner_only','Only the household owner can update source status.');const canonical=validateData(kind,b.data);const key=keyFor(request,b.id);const fingerprint=await digest(stable({kind,data:canonical}));const id='item_'+(await digest('create:'+key)).slice(0,32);const now=new Date().toISOString();const op='create:'+key;
 const prior=await db.prepare('SELECT fingerprint,result_json FROM hub_operations WHERE operation_key=?').bind(op).first<Operation>();
 if(prior){if(prior.fingerprint!==fingerprint)throw new ApiError(409,'idempotency_conflict','This action key was already used for different data.');try{return json({record:record(await find(db,JSON.parse(prior.result_json).id))},201);}catch(e){if(e instanceof ApiError&&e.status===404)throw new ApiError(410,'item_deleted','This previously saved item was deleted. Start a new action to create another.');throw e;}}
 const data=await preparedData(db,kind,canonical);const nonce=crypto.randomUUID();
 await db.batch([
  db.prepare('INSERT INTO hub_operations(operation_key,fingerprint,result_json,created_at) VALUES(?,?,?,?) ON CONFLICT(operation_key) DO NOTHING').bind(op,fingerprint,JSON.stringify({id,nonce}),now),
  db.prepare("INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) SELECT ?,?,?,1,?,?,? WHERE EXISTS(SELECT 1 FROM hub_operations WHERE operation_key=? AND fingerprint=? AND json_extract(result_json,'$.nonce')=?) ON CONFLICT(id) DO NOTHING").bind(id,kind,JSON.stringify(data),now,now,userId,op,fingerprint,nonce)
 ]);
 const saved=await db.prepare('SELECT fingerprint,result_json FROM hub_operations WHERE operation_key=?').bind(op).first<Operation>();if(!saved||saved.fingerprint!==fingerprint)throw new ApiError(409,'idempotency_conflict','This action key was already used for different data.');const savedId=JSON.parse(saved.result_json).id as string;
 const row=await find(db,savedId);return json({record:record(row)},201);
}
async function updateItem(request:Request,db:D1Database,userId:string,id:string,admin:boolean):Promise<Response> {
 const b=await body(request);const expected=version(b.version);const old=await find(db,id);if(old.kind==='source'&&!admin)throw new ApiError(403,'owner_only','Only the household owner can update source status.');if(old.version!==expected)throw new ApiError(409,'version_conflict','This item changed on another device. Refresh and try again.');
 if(request.method==='DELETE'){
  // Recipe snapshots on meals deliberately survive deletion of the source recipe.
  const result=await db.prepare('DELETE FROM hub_records WHERE id=? AND version=?').bind(id,expected).run();if(!result.meta.changes)throw new ApiError(409,'version_conflict','This item changed on another device.');return json({deleted:true,id});
 }
 const data=await preparedData(db,old.kind,{...JSON.parse(old.data),...object(b.data)},old);const now=new Date().toISOString();const result=await db.prepare('UPDATE hub_records SET data=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND version=?').bind(JSON.stringify(data),now,userId,id,expected).run();if(!result.meta.changes)throw new ApiError(409,'version_conflict','This item changed on another device. Refresh and try again.');return json({record:record(await find(db,id))});
}
async function importIngredients(request:Request,db:D1Database,userId:string,id:string,sourceKind:'meal'|'recipe'='meal'):Promise<Response> {
 const b=await body(request);const meal=await find(db,id);if(meal.kind!==sourceKind)throw new ApiError(400,'invalid_recipe','Choose a saved recipe or planned meal.');const m=JSON.parse(meal.data) as Data;if(sourceKind==='meal'&&!m.recipeSnapshot)throw new ApiError(400,'no_recipe','This meal has no recipe ingredients.');const recipe=sourceKind==='recipe'?m:object(m.recipeSnapshot);const servings=Number(b.servings??m.servings??recipe.servings);const excluded=b.excludedIngredientNames??[];if(!Array.isArray(excluded)||excluded.length>100||excluded.some(v=>typeof v!=='string'))throw new ApiError(400,'invalid_input','Choose ingredients to exclude.');const listName=string(b.listName??'Groceries','List');const ingredients=scaledIngredients(recipe,Number(servings),excluded as string[]);keyFor(request);const fingerprint=await digest(stable({id,listName,servings,excluded:[...excluded].sort(),ingredients}));const op='ingredients:'+fingerprint;const now=new Date().toISOString();const nonce=crypto.randomUUID();const ids=await Promise.all(ingredients.map(async(_,i)=>'ingredient_'+(await digest(op+':'+i)).slice(0,32)));
 const statements:D1PreparedStatement[]=[db.prepare('INSERT INTO hub_operations(operation_key,fingerprint,result_json,created_at) VALUES(?,?,?,?) ON CONFLICT(operation_key) DO NOTHING').bind(op,fingerprint,JSON.stringify({ids,nonce}),now)];
 ingredients.forEach((ingredient,i)=>{
  const quantity=[ingredient.amount,ingredient.unit].filter(v=>v!==undefined&&v!=='').join(' ');const data=validateData('shopping',{title:ingredient.name,listName,quantity,amount:ingredient.amount,unit:ingredient.unit,done:false,...(sourceKind==='meal'?{sourceMealId:id}:{sourceRecipeId:id})});
  statements.push(db.prepare('INSERT INTO hub_records(id,kind,data,version,created_at,updated_at,updated_by) SELECT ?,\'shopping\',?,1,?,?,? WHERE EXISTS(SELECT 1 FROM hub_operations WHERE operation_key=? AND fingerprint=? AND json_extract(result_json,\'$.nonce\')=?) ON CONFLICT(id) DO NOTHING').bind(ids[i],JSON.stringify(data),now,now,userId,op,fingerprint,nonce));
 });
 await db.batch(statements);const saved=await db.prepare('SELECT fingerprint,result_json FROM hub_operations WHERE operation_key=?').bind(op).first<Operation>();if(!saved||saved.fingerprint!==fingerprint)throw new ApiError(409,'idempotency_conflict','This import key was already used for another selection.');const savedIds=JSON.parse(saved.result_json).ids as string[];const rows=await Promise.all(savedIds.map(async x=>{try{return record(await find(db,x));}catch(e){if(e instanceof ApiError&&e.status===404)return null;throw e;}}));return json({records:rows.filter(Boolean),importedCount:rows.filter(Boolean).length});
}
async function adminRoute(request:Request,db:D1Database,path:string):Promise<Response> {
 if(path==='/api/admin'&&request.method==='GET'){const results=await db.prepare('SELECT id,data,version,created_at,updated_at FROM hub_admin_results ORDER BY updated_at DESC LIMIT 501').all<{id:string;data:string;version:number;created_at:string;updated_at:string}>();if(results.results.length>500)throw new ApiError(503,'result_limit','Admin result limit reached.');return json({results:results.results.map(r=>({id:r.id,...JSON.parse(r.data),version:r.version,createdAt:r.created_at,updatedAt:r.updated_at})),serverTime:new Date().toISOString()});}
 const match=path.match(/^\/api\/admin\/results\/([a-zA-Z0-9_-]+)$/);if(match&&request.method==='PUT'){
  const id=identifier(match[1]);const b=await body(request);const data=validateAdmin(b.data??b);const old=await db.prepare('SELECT workflow,source_id,version FROM hub_admin_results WHERE id=?').bind(id).first<{workflow:string;source_id:string;version:number}>();const now=new Date().toISOString();
  if(old){if(old.workflow!==data.workflow||old.source_id!==data.sourceId)throw new ApiError(409,'workflow_conflict','A workflow may only update its own result.');const expected=version(b.version);const update=await db.prepare('UPDATE hub_admin_results SET data=?,version=version+1,updated_at=? WHERE id=? AND version=?').bind(JSON.stringify(data),now,id,expected).run();if(!update.meta.changes)throw new ApiError(409,'version_conflict','This result changed; reload before updating.');}
  else {await db.prepare('INSERT INTO hub_admin_results(id,workflow,source_id,data,version,created_at,updated_at) VALUES(?,?,?,?,1,?,?)').bind(id,data.workflow,data.sourceId,JSON.stringify(data),now,now).run();}
  return json({result:{id,...data,version:old?old.version+1:1}});
 }
 throw new ApiError(404,'not_found','Unknown admin endpoint.');
}
export async function handleApi(request:Request,env:HubBindings):Promise<Response> {
 try {
  const path=new URL(request.url).pathname;const userId=request.headers.get('oai-authenticated-user-id');if(!userId)throw new ApiError(401,'authentication_required','Sign in with ChatGPT to open your private family hub.');if(!env.DB)throw new ApiError(503,'storage_unavailable','Shared storage has not been connected yet.');
  if(!['GET','HEAD'].includes(request.method))checkOrigin(request);const role=await membership(env.DB,userId,request.headers.get('oai-authenticated-user-email'));const admin=role==='owner';if(admin)await applyBootstrap(env.DB,env.HUB_BOOTSTRAP_JSON,userId);
  if(path.startsWith('/api/admin')){if(!admin)throw new ApiError(403,'owner_only','This area is private to the household owner.');return await adminRoute(request,env.DB,path);}
  if(path==='/api/permissions'&&request.method==='GET')return json({admin});
  if(path==='/api/state'&&request.method==='GET')return json(await state(env.DB,admin));
  if(path==='/api/export'&&request.method==='GET'){const after=new URL(request.url).searchParams.get('after')??'';if(after.length>150)throw new ApiError(400,'invalid_input','Invalid export cursor.');const rows=await env.DB.prepare('SELECT id,kind,data,version,created_at,updated_at FROM hub_records WHERE id>? ORDER BY id LIMIT 2501').bind(after).all<Row>();const hasMore=rows.results.length>2500;const selected=rows.results.slice(0,2500);return json({format:'bird-family-hub',version:1,exportedAt:new Date().toISOString(),records:selected.map(record),nextCursor:hasMore?selected.at(-1)?.id:null});}
  if(path==='/api/members/invites'&&request.method==='POST'){if(!admin)throw new ApiError(403,'owner_only','Only the household owner can invite a member.');const b=await body(request);const email=string(b.email,'Email',254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new ApiError(400,'invalid_input','Enter the member’s exact ChatGPT email address.');const displayName=string(b.displayName,'Name');await env.DB.prepare('INSERT INTO hub_invites(email,display_name,created_at) VALUES(?,?,?) ON CONFLICT(email) DO UPDATE SET display_name=excluded.display_name').bind(email,displayName,new Date().toISOString()).run();return json({invited:true,displayName,note:'Household invitation saved. Private Site access must also be granted to the exact same ChatGPT email through Sites sharing controls.'});}
  if(path==='/api/members'){
   if(!admin)throw new ApiError(403,'owner_only','Only the household owner can manage membership.');
   if(request.method==='GET'){const members=await env.DB.prepare('SELECT user_id AS userId,display_name AS displayName,role,created_at AS createdAt FROM hub_members ORDER BY created_at').all();return json({members:members.results});}
   if(request.method==='POST'){const b=await body(request);const id=string(b.userId,'Platform user ID',250);const name=string(b.displayName,'Name');await env.DB.prepare("INSERT INTO hub_members(user_id,display_name,role,created_at) VALUES(?,?,'member',?) ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name").bind(id,name,new Date().toISOString()).run();return json({added:true,note:'The owner must also grant private Site access using Sites sharing controls.'});}
  }
  if(path==='/api/items'&&request.method==='POST')return await createItem(request,env.DB,userId,admin);
  const ingredients=path.match(/^\/api\/meals\/([a-zA-Z0-9_-]+)\/ingredients$/);if(ingredients&&request.method==='POST')return await importIngredients(request,env.DB,userId,ingredients[1]);
  const recipeIngredients=path.match(/^\/api\/recipes\/([a-zA-Z0-9_-]+)\/ingredients$/);if(recipeIngredients&&request.method==='POST')return await importIngredients(request,env.DB,userId,recipeIngredients[1],'recipe');
  const item=path.match(/^\/api\/items\/([a-zA-Z0-9_-]+)$/);if(item&&['PATCH','DELETE'].includes(request.method))return await updateItem(request,env.DB,userId,item[1],admin);
  throw new ApiError(404,'not_found','Unknown hub endpoint.');
 }catch(e){if(e instanceof ApiError)return json({error:{code:e.code,message:e.message}},e.status);if(e instanceof Error&&(/UNIQUE constraint failed/.test(e.message)))return json({error:{code:'record_conflict',message:'A record already exists for this meal slot, item ID or workflow source. Refresh before trying again.'}},409);return json({error:{code:'server_error',message:'The change could not be completed. Please refresh before retrying.'}},500);}
}
